import React from 'react';

interface CounterProps {
  initialCount?: number;
}

const Counter: React.FC<CounterProps> = ({ initialCount = 0 }) => {
  const [count, setCount] = React.useState<number>(initialCount);

  const increment = () => setCount((prev) => prev + 1);

  const decrement = () => setCount((prev) => Math.max(0, prev - 1));

  // Basic inline styles for a clean look
  const containerStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column' as const,
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  };

  const headingStyle: React.CSSProperties = {
    fontSize: '4rem',
    fontWeight: 700,
    margin: '2rem 0',
    color: '#1f2937', // gray-800
  };

  const buttonBaseStyle: React.CSSProperties = {
    padding: '0.75rem 1.5rem',
    fontSize: '1rem',
    fontWeight: 600,
    borderRadius: '0.5rem',
    border: 'none',
    cursor: 'pointer',
    transition: 'background-color 0.2s ease, transform 0.1s ease',
    outline: 'none',
  };

  const incrementStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: '#3b82f6', // blue-500
    color: 'white',
  };

  const decrementStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    backgroundColor: '#ef4444', // red-500
    color: 'white',
  };

  return (
    <div style={containerStyle}>
      <h1 style={headingStyle}>{count}</h1>
      <div style={{ display: 'flex', gap: '1rem' }}>
        <button onClick={decrement} style={decrementStyle}>
          Decrement
        </button>
        <button onClick={increment} style={incrementStyle}>
          Increment
        </button>
      </div>
    </div>
  );
};

export default Counter;
